def letter_stats(s: str) -> dict[str, int]:
    stats = {'vowels': 0, 'consonants': 0, 'digits': 0, 'other': 0}
    vowels_set = set("aeiouAEIOU")
    for char in s:
        if char.isspace():
            continue
        if char.isdigit():
            stats['digits'] += 1
        elif char.isalpha():
            if char in vowels_set:
                stats['vowels'] += 1
            else:
                stats['consonants'] += 1
        else:
            stats['other'] += 1
    return stats
